function startOrder(modules) {
  const byName = new Map(modules.map((m) => [m.name, m]));
  const ordered = [];
  const visit = (m) => {
    if (ordered.includes(m)) return;
    for (const name of m.dependsOn ?? []) {
      const dependency = byName.get(name);
      if (dependency === undefined) throw new Error(`"${m.name}" needs "${name}", which is not registered`);
      visit(dependency);
    }
    ordered.push(m);
  };
  modules.forEach(visit);
  return ordered;
}

