function startOrder(modules) {
  const byName = new Map(modules.map((m) => [m.name, m]));
  const ordered = [];
  const visiting = new Set();
  const visit = (m) => {
    if (ordered.includes(m)) return;
    if (visiting.has(m.name)) throw new Error(`Circular dependency at "${m.name}"`);
    visiting.add(m.name);
    for (const name of m.dependsOn ?? []) visit(byName.get(name));
    ordered.push(m);
  };
  modules.forEach(visit);
  return ordered;
}

