function checkDependencies(modules) {
  const names = new Set(modules.map((module) => module.name));
  const problems = [];
  for (const module of modules) {
    for (const name of module.dependsOn ?? []) {
      if (!names.has(name)) problems.push(`${module.name} needs ${name}`);
    }
  }
  return problems;
}

